/**
 * CandlestickChart.js - Interactive Candlestick Chart
 * Professional trading chart with predictions
 */

import React, { useEffect, useRef } from 'react';
import { createChart } from 'lightweight-charts';

const CandlestickChart = ({ ticker, currentPrice, predictedPrice }) => {
  const chartContainerRef = useRef();

  useEffect(() => {
    if (!chartContainerRef.current) return;

    // Create chart with dark theme
    const chart = createChart(chartContainerRef.current, {
      width: chartContainerRef.current.clientWidth,
      height: 400,
      layout: {
        background: { type: 'solid', color: 'transparent' },
        textColor: '#d1d5db',
      },
      grid: {
        vertLines: { color: 'rgba(255, 255, 255, 0.05)' },
        horzLines: { color: 'rgba(255, 255, 255, 0.05)' },
      },
      crosshair: {
        mode: 1,
      },
      rightPriceScale: {
        borderColor: 'rgba(255, 255, 255, 0.1)',
      },
      timeScale: {
        borderColor: 'rgba(255, 255, 255, 0.1)',
        timeVisible: true,
      },
    });

    // Generate sample data
    const candleData = generateCandleData(currentPrice, 60);
    
    // Create candlestick series correctly
    const candleSeries = chart.addSeries({
      type: 'Candlestick',
      upColor: '#10b981',
      downColor: '#ef4444',
      borderUpColor: '#10b981',
      borderDownColor: '#ef4444',
      wickUpColor: '#10b981',
      wickDownColor: '#ef4444',
    });
    
    candleSeries.setData(candleData);

    // Add SMA lines
    const sma20 = calculateSMA(candleData, 20);
    const sma20Series = chart.addSeries({
      type: 'Line',
      color: '#3b82f6',
      lineWidth: 2,
    });
    sma20Series.setData(sma20);

    const sma50 = calculateSMA(candleData, 50);
    const sma50Series = chart.addSeries({
      type: 'Line',
      color: '#8b5cf6',
      lineWidth: 2,
    });
    sma50Series.setData(sma50);

    // Add prediction line
    const lastCandle = candleData[candleData.length - 1];
    const predictionData = [
      { time: lastCandle.time, value: currentPrice },
      { time: lastCandle.time + 86400, value: predictedPrice },
    ];
    
    const predictionSeries = chart.addSeries({
      type: 'Line',
      color: '#f59e0b',
      lineWidth: 3,
      lineStyle: 2,
    });
    predictionSeries.setData(predictionData);

    // Handle resize
    const handleResize = () => {
      if (chartContainerRef.current) {
        chart.applyOptions({
          width: chartContainerRef.current.clientWidth,
        });
      }
    };

    window.addEventListener('resize', handleResize);
    chart.timeScale().fitContent();

    return () => {
      window.removeEventListener('resize', handleResize);
      chart.remove();
    };
  }, [currentPrice, predictedPrice]);

  return <div ref={chartContainerRef} style={{ width: '100%', borderRadius: '12px' }} />;
};

// Helper functions
function generateCandleData(basePrice, days) {
  const data = [];
  let price = basePrice * 0.85;
  const now = Math.floor(Date.now() / 1000);

  for (let i = days; i >= 0; i--) {
    const time = now - (i * 86400);
    const volatility = price * 0.02;
    const open = price;
    const close = open + (Math.random() - 0.48) * volatility;
    const high = Math.max(open, close) + Math.random() * volatility * 0.5;
    const low = Math.min(open, close) - Math.random() * volatility * 0.5;

    data.push({ time, open, high, low, close });
    price = close;
  }

  return data;
}

function calculateSMA(data, period) {
  const sma = [];
  for (let i = period - 1; i < data.length; i++) {
    let sum = 0;
    for (let j = 0; j < period; j++) {
      sum += data[i - j].close;
    }
    sma.push({ time: data[i].time, value: sum / period });
  }
  return sma;
}

export default CandlestickChart;
